steps.input_schema:
{
  "type": "object",
  "required": [
    "to",
    "subject",
    "bodyType",
    "body"
  ],
  "properties": {
    "to": {
      "type": "string",
      "title": "To",
      "minLength": 3,
      "description": "Enter the user's email ID to whom you want to send the email. You can add multiple email IDs separated by a comma."
    },
    "subject": {
      "type": "string",
      "title": "Subject",
      "minLength": 3,
      "description": "Enter the subject of the email"
    },
    "bodyType": {
      "type": "string",
      "title": "Body Type",
      "enum": [
        "Text",
        "HTML"
      ],
      "description": "Select the body type."
    },
    "body": {
      "type": "string",
      "title": "Body",
      "format": "textarea",
      "description": "Enter your message in the above-selected format.",
      "minLength": 5
    },
    "cc": {
      "type": "string",
      "title": "Cc",
      "description": "Enter the user's email ID to whom you want to Cc in the email. You can add multiple email IDs separated by a comma."
    },
    "bcc": {
      "type": "string",
      "title": "Bcc",
      "description": "Enter the user's email ID to whom you want to Bcc in the email. You can add multiple email IDs separated by a comma."
    }
  }
}
